using System.Collections.Immutable;

namespace ConfigurationSourceGen.Validations;

public sealed class MinLengthValidator : IGenerateValidator {

    public string AttributeName { get; } = "MinLengthAttribute";

    public string GenerateAttributeSource(string ns) => $$"""
        // <auto-generated/>
        namespace {{ns}};

        [global::System.AttributeUsage(global::System.AttributeTargets.Property, AllowMultiple = false, Inherited = true)]
        public sealed class MinLengthAttribute : global::System.Attribute {
            public int Length { get; }

            public MinLengthAttribute(int length) {
                Length = length;
            }
        }
        """;

    public void Generate(CodeBuilder builder, ToGenerateProperty property, AttributeDefinition attribute, string valueExpression) {

        if (!ValidationGeneratorHelper.TryGetIntArgument(attribute, 0, out int minLength)) {
            return;
        }

        builder.If($"{valueExpression}.Length < {minLength}", () => {
            ValidationGeneratorHelper.AddError(
                builder,
                property.Name,
                $"must contain at least {minLength} characters.");
        });
    }
}